I'll start by exploring the weight structure and computing basic statistics for the three models.

```python
import numpy as np, itertools
models=["A","B","C"]
big_layers=[f"block{b}.{n}" for b in [4,5,6,7] for n in ["attn.in_proj_weight","attn.out_proj.weight","mlp.fc1.weight","mlp.fc2.weight"]]
big={m:{l:weights[m][l] for l in big_layers} for m in models}
print("shapes:", {l: weights["A"][l].shape for l in big_layers[:2]}, "keys per model:", len(weights["A"]))

print("\nFrobenius norms of big layers:")
print("layer".ljust(28), "A".rjust(8), "B".rjust(8), "C".rjust(8))
for l in big_layers:
    print(l.ljust(28), " ".join(f"{np.linalg.norm(big[m][l]):10.2f}" for m in models))

def flat(m):
    return np.concatenate([weights[m][k].ravel() for k in sorted(weights[m].keys())])
F={m:flat(m) for m in models}
print("\nTotal L2 distance over all params of blocks 4-7:")
for a,b in itertools.combinations(models,2):
    d=np.linalg.norm(F[a]-F[b]); print(f"  d({a},{b}) = {d:.4f}   rel(A-norm) = {d/np.linalg.norm(F[a]):.4f}")

print("\nLayerNorm stats (||gamma-1||, ||bias||):")
for b in [4,5,6,7]:
    for ln in ["ln_1","ln_2"]:
        k=f"block{b}.{ln}"
        row=[]
        for m in models:
            g=weights[m][k+".weight"]; be=weights[m][k+".bias"]
            row.append(f"{np.linalg.norm(g-1):.3f}/{np.linalg.norm(be):.3f}")
        print(k.ljust(14), "  ".join(f"{m}:{v}" for m,v in zip(models,row)))
